#!/usr/bin/env python3
"""rag_hybrid_update.py -- deploys the current Hybrid RAG application
state (commit 742d990 plus all subsequent working-tree fixes) onto an
existing company-knowledge-search installation on Windows.

WHAT THIS DOES
    Writes the current application-code files (embedded below as base64
    text) -- the original Hybrid RAG upgrade plus everything added since:
    the P0 Jan reasoning/token-budget fix (jan_disable_thinking default
    on, max_tokens default 700, ProviderGenerationLimitError, the
    one-time bounded generation-limit retry, reasoning-field diagnostics
    that never expose the reasoning text itself), the sidebar sync-report
    layout fix, source citation de-duplication, temporal "latest
    progress" query handling, EmbeddingGemma auto-start via start.bat,
    and the ChatGPT-like Q&A redesign (a single centered rounded
    composer with an integrated small send button instead of the old
    full-width blue button, per-document numbered citations rendered as
    compact superscripts with a matching numbered source list below the
    answer, a McKinsey-style conclusion-first/MECE answer prompt, and
    executive-writing trailing-period cleanup). Backs up whatever it is
    about to replace into a timestamped folder first, then runs the
    application's own idempotent, additive-only schema migration
    (src.database.initialize_schema) against your EXISTING SQLite
    database so it gains the chunk_embeddings table (and Excel
    provenance columns) without losing or rewriting a single existing
    row.

WHAT THIS NEVER TOUCHES
    Company documents/PDFs/PPT/DOCX/XLSX, your existing SQLite database
    file itself (only additive ALTER TABLE / CREATE TABLE IF NOT EXISTS
    via the app's own migration code -- never deleted or replaced),
    embeddings/index data, Gemma/EmbeddingGemma GGUF files, .venv, venv,
    .git, .env, data/config.json, logs, caches, or anything not
    explicitly listed in FILES below. No corporate data, model weights,
    or machine-specific configuration are embedded in this script, and it
    makes no network calls of its own (the optional dependency-install
    step is the only thing that could reach the internet, and only for
    package names already missing from your environment).

USAGE (on the Windows machine, no Git required)
    1. Copy this single file anywhere convenient (e.g. Desktop).
    2. Run:
           py rag_hybrid_update.py
    3. It will try to find your existing company-knowledge-search folder
       automatically; if it can't, it will ask you to type the path.
    4. When it reports success, follow the "Next steps" it prints.

Standard library only. Works on Windows with Python 3.14 (and other
platforms/versions with a comparable stdlib).
"""

